-- Phase 4B: additive, versioned curriculum architecture and shadow mapping.
-- This migration intentionally does not alter lesson_library or activate any
-- parent-facing coverage, recommendation, entitlement, or personalization path.
begin;

create table public.curriculum_domains (
  domain_key text primary key,
  category_key text not null check (category_key in ('communication','daily_routines','emotions_behavior','learning_attention','movement_coordination','play_social_skills')),
  internal_name text not null,
  parent_display_name text not null,
  definition text not null,
  sort_order integer not null check (sort_order > 0),
  architecture_version integer not null check (architecture_version > 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (category_key, domain_key, architecture_version)
);

create table public.authoritative_curriculum_skills (
  skill_key text primary key,
  domain_key text not null references public.curriculum_domains(domain_key) on delete restrict,
  internal_name text not null,
  parent_display_name text not null,
  definition text not null,
  scope_boundary text not null,
  communication_safeguard text,
  feeding_safeguard text,
  sensitivity text not null check (sensitivity in ('standard','high_scrutiny')),
  core_stage_count integer not null check (core_stage_count between 1 and 4),
  has_optional_stage_5 boolean not null default false,
  architecture_version integer not null check (architecture_version > 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (domain_key, internal_name, architecture_version)
);

create table public.curriculum_stage_definitions (
  stage_definition_id text primary key,
  skill_key text not null references public.authoritative_curriculum_skills(skill_key) on delete restrict,
  stage_number integer not null check (stage_number between 1 and 5),
  stage_key text not null,
  display_name text not null,
  definition text not null,
  is_core boolean not null,
  is_generalization boolean not null,
  sort_order integer not null check (sort_order between 1 and 5),
  architecture_version integer not null check (architecture_version > 0),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (not is_generalization or (stage_number = 5 and not is_core)),
  unique (skill_key, stage_number, architecture_version),
  unique (skill_key, stage_key, architecture_version)
);

create table public.lesson_curriculum_mappings (
  id uuid primary key default gen_random_uuid(),
  lesson_id uuid not null references public.lesson_library(id) on delete restrict,
  architecture_version integer not null check (architecture_version > 0),
  domain_key text references public.curriculum_domains(domain_key) on delete restrict,
  skill_key text references public.authoritative_curriculum_skills(skill_key) on delete restrict,
  stage_definition_id text references public.curriculum_stage_definitions(stage_definition_id) on delete restrict,
  mapping_status text not null check (mapping_status in ('mapped','unresolved','retirement')),
  mapping_confidence text not null check (mapping_confidence in ('high','medium','low')),
  content_disposition text not null check (content_disposition in ('keep_as_is_structurally','keep_content_remap_taxonomy','rewrite_content','differentiate_from_duplicate','retire_duplicate','retire_fallback','approved_retirement','high_scrutiny_review','unresolved_concept')),
  duplicate_group text,
  owner_decision_required boolean not null default false,
  requires_content_rewrite boolean not null default false,
  requires_taxonomy_change boolean not null default false,
  sensitivity text not null check (sensitivity in ('standard','high_scrutiny')),
  recommendation_eligibility text not null check (recommendation_eligibility in ('shadow_candidate','review_required','excluded')),
  time_of_day_relevance text not null check (time_of_day_relevance in ('morning_priority','evening_priority','context_dependent','time_neutral','unresolved')),
  communication_scope text not null check (communication_scope in ('none','communication_method_inclusive','speech_production_review')),
  feeding_scope text not null check (feeding_scope in ('none','food_scope_review','consumption_concern_unresolved')),
  legacy_skill_id uuid,
  legacy_stage_id uuid,
  legacy_category text not null,
  legacy_skill_area text not null,
  legacy_stage_number integer not null,
  legacy_stage_name text not null,
  source text not null,
  is_active_primary boolean not null default false,
  notes text not null default '',
  reviewed_by uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((mapping_status = 'mapped' and domain_key is not null and skill_key is not null and stage_definition_id is not null) or mapping_status <> 'mapped'),
  check (mapping_status = 'mapped' or recommendation_eligibility = 'excluded'),
  check (sensitivity <> 'high_scrutiny' or recommendation_eligibility <> 'shadow_candidate'),
  unique (lesson_id, architecture_version)
);

create unique index lesson_curriculum_mappings_one_active_primary_idx
  on public.lesson_curriculum_mappings (lesson_id)
  where is_active_primary;
create index lesson_curriculum_mappings_shadow_review_idx
  on public.lesson_curriculum_mappings (architecture_version,mapping_status,content_disposition,recommendation_eligibility);
create index curriculum_stage_definitions_skill_order_idx
  on public.curriculum_stage_definitions (skill_key,sort_order);

alter table public.curriculum_domains enable row level security;
alter table public.authoritative_curriculum_skills enable row level security;
alter table public.curriculum_stage_definitions enable row level security;
alter table public.lesson_curriculum_mappings enable row level security;

revoke all on public.curriculum_domains from public,anon,authenticated;
revoke all on public.authoritative_curriculum_skills from public,anon,authenticated;
revoke all on public.curriculum_stage_definitions from public,anon,authenticated;
revoke all on public.lesson_curriculum_mappings from public,anon,authenticated;
grant select,insert,update,delete on public.curriculum_domains to authenticated;
grant select,insert,update,delete on public.authoritative_curriculum_skills to authenticated;
grant select,insert,update,delete on public.curriculum_stage_definitions to authenticated;
grant select,insert,update,delete on public.lesson_curriculum_mappings to authenticated;

create policy "Authenticated users read active curriculum domains"
on public.curriculum_domains for select to authenticated using (is_active);
create policy "Authenticated users read active authoritative skills"
on public.authoritative_curriculum_skills for select to authenticated using (is_active);
create policy "Authenticated users read active stage definitions"
on public.curriculum_stage_definitions for select to authenticated using (is_active);

create policy "App admins manage curriculum domains"
on public.curriculum_domains for all to authenticated using (public.is_app_admin()) with check (public.is_app_admin());
create policy "App admins manage authoritative skills"
on public.authoritative_curriculum_skills for all to authenticated using (public.is_app_admin()) with check (public.is_app_admin());
create policy "App admins manage stage definitions"
on public.curriculum_stage_definitions for all to authenticated using (public.is_app_admin()) with check (public.is_app_admin());
create policy "App admins manage shadow lesson mappings"
on public.lesson_curriculum_mappings for all to authenticated using (public.is_app_admin()) with check (public.is_app_admin());

on conflict (domain_key) do update set category_key=excluded.category_key,internal_name=excluded.internal_name,parent_display_name=excluded.parent_display_name,definition=excluded.definition,sort_order=excluded.sort_order,architecture_version=excluded.architecture_version,updated_at=now();

on conflict (skill_key) do update set domain_key=excluded.domain_key,internal_name=excluded.internal_name,parent_display_name=excluded.parent_display_name,definition=excluded.definition,scope_boundary=excluded.scope_boundary,communication_safeguard=excluded.communication_safeguard,feeding_safeguard=excluded.feeding_safeguard,sensitivity=excluded.sensitivity,core_stage_count=excluded.core_stage_count,has_optional_stage_5=excluded.has_optional_stage_5,architecture_version=excluded.architecture_version,updated_at=now();

on conflict (stage_definition_id) do update set display_name=excluded.display_name,definition=excluded.definition,is_core=excluded.is_core,is_generalization=excluded.is_generalization,sort_order=excluded.sort_order,architecture_version=excluded.architecture_version,updated_at=now();

on conflict (lesson_id,architecture_version) do update set domain_key=excluded.domain_key,skill_key=excluded.skill_key,stage_definition_id=excluded.stage_definition_id,mapping_status=excluded.mapping_status,mapping_confidence=excluded.mapping_confidence,content_disposition=excluded.content_disposition,duplicate_group=excluded.duplicate_group,owner_decision_required=excluded.owner_decision_required,requires_content_rewrite=excluded.requires_content_rewrite,requires_taxonomy_change=excluded.requires_taxonomy_change,sensitivity=excluded.sensitivity,recommendation_eligibility=excluded.recommendation_eligibility,time_of_day_relevance=excluded.time_of_day_relevance,communication_scope=excluded.communication_scope,feeding_scope=excluded.feeding_scope,legacy_skill_id=excluded.legacy_skill_id,legacy_stage_id=excluded.legacy_stage_id,legacy_category=excluded.legacy_category,legacy_skill_area=excluded.legacy_skill_area,legacy_stage_number=excluded.legacy_stage_number,legacy_stage_name=excluded.legacy_stage_name,source=excluded.source,is_active_primary=false,notes=excluded.notes,updated_at=now();

do $$
declare domain_count integer;skill_count integer;stage_count integer;mapping_count integer;
begin
 select count(*) into domain_count from public.curriculum_domains where architecture_version=1;
 select count(*) into skill_count from public.authoritative_curriculum_skills where architecture_version=1;
 select count(*) into stage_count from public.curriculum_stage_definitions where architecture_version=1;
 select count(*) into mapping_count from public.lesson_curriculum_mappings where architecture_version=1;
 if domain_count<>21 or skill_count<>54 or stage_count<>264 or mapping_count<>299 then
   raise exception 'Phase 4B seed count mismatch: domains %, skills %, stages %, mappings %',domain_count,skill_count,stage_count,mapping_count;
 end if;
 if exists(select 1 from public.lesson_curriculum_mappings where architecture_version=1 and is_active_primary) then
   raise exception 'Phase 4B mappings must remain shadow/non-authoritative.';
 end if;
end $$;

commit;
