values
('communication.requesting','functional_communication','Requesting','Requesting','Builds requesting through meaningful, caregiver-supported home activities.','Limited to functional, caregiver-facing requesting learning within ABA at Home product scope.',null,null,'standard',4,true,1),
('communication.self_advocacy','functional_communication','Self-Advocacy','Self-Advocacy','Builds self-advocacy through meaningful, caregiver-supported home activities.','Limited to functional, caregiver-facing self-advocacy learning within ABA at Home product scope.',null,null,'standard',4,true,1),
('communication.non_speaking_social','functional_communication','Non-Speaking & Social Communication','Non-Speaking & Social Communication','Builds non-speaking & social communication through meaningful, caregiver-supported home activities.','Limited to functional, caregiver-facing non-speaking & social communication learning within ABA at Home product scope.',null,null,'standard',4,true,1),
('communication.following_directions','understanding_conversation','Following Directions','Following Directions','Builds following directions through meaningful, caregiver-supported home activities.','Teaches understanding and participation in functional directions, never generalized obedience; refusal, self-advocacy, breaks, and support remain available.',null,null,'standard',4,true,1),
('communication.answering_questions','understanding_conversation','Answering Questions','Answering Questions','Builds answering questions through meaningful, caregiver-supported home activities.','Limited to functional, caregiver-facing answering questions learning within ABA at Home product scope.',null,null,'standard',4,true,1),
